UPDATE account_travel_context
SET country_or_region = #{countryOrRegion}, city = #{city}, trip_start_date = #{tripStartDate},
    trip_end_date = #{tripEndDate}, assistance_needs = #{assistanceNeeds},
    version = version + 1, updated_at = #{updatedAt}
WHERE account_id = #{accountId} AND version = #{expectedVersion}

UPDATE account_travel_context
SET country_or_region = NULL, city = NULL, trip_start_date = NULL, trip_end_date = NULL,
    assistance_needs = NULL, version = version + 1, updated_at = #{updatedAt}
WHERE account_id = #{accountId} AND version = #{expectedVersion}
